CREATE OR REPLACE PROCEDURE hcbi_ras.pkg_stg_anag_provincia_prc_main(IN p_id_chain_log bigint, IN p_id_chain bigint, IN p_id_step bigint, IN p_ds_step_name character varying, OUT p_result integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'hcbi_ras', 'hcbi_utility'
AS $procedure$
DECLARE v_id_log bigint; v_selected bigint:=0; v_inserted bigint:=0; v_updated bigint:=0; v_deleted bigint:=0; v_rec_errors bigint:=0;     v_sqlstate text; v_sqlerrm text; v_sql_detail text; v_sql_hint text; v_sql_context text; v_log_error text;
BEGIN p_result:=-1; SELECT hcbi_utility.pkg_log_fnc_insert_log(p_id_chain_log,p_id_chain,p_id_step,p_ds_step_name,clock_timestamp()::timestamp,clock_timestamp()::timestamp,p_ds_step_name) INTO v_id_log;
 DROP TABLE IF EXISTS hcbi_ras.tmp_anag_provincia_classificata; CREATE TABLE hcbi_ras.tmp_anag_provincia_classificata AS
 WITH src AS MATERIALIZED(SELECT f.id_sorgente_provincia id_sorgente_provincia_raw,f.cd_provincia cd_provincia_raw,f.ds_nome ds_nome_raw,f.id_sorgente_area_vasta id_sorgente_area_vasta_raw,f.fl_provincia_principale_regionale fl_provincia_principale_regionale_raw,f.fl_provincia_principale_area_vasta fl_provincia_principale_area_vasta_raw,nullif(btrim(f.id_sorgente_provincia),'') id_sorgente_provincia_txt,nullif(btrim(f.cd_provincia),'') cd_provincia_txt,nullif(btrim(f.ds_nome),'') ds_nome_txt,nullif(btrim(f.id_sorgente_area_vasta),'') id_sorgente_area_vasta_txt,nullif(btrim(f.fl_provincia_principale_regionale),'') fl_provincia_principale_regionale_txt,nullif(btrim(f.fl_provincia_principale_area_vasta),'') fl_provincia_principale_area_vasta_txt,count(*) OVER(PARTITION BY nullif(btrim(f.cd_provincia),'')) duplicate_count FROM hcbi_ras.v_src_tmp_anag_provincia f),
 cv AS MATERIALIZED(SELECT s.*,hcbi_ras.try_bigint(id_sorgente_provincia_txt) id_sorgente_provincia_cv,hcbi_ras.try_bigint(id_sorgente_area_vasta_txt) id_sorgente_area_vasta_cv,hcbi_ras.try_boolean_smallint(fl_provincia_principale_regionale_txt) fl_provincia_principale_regionale_cv,hcbi_ras.try_boolean_smallint(fl_provincia_principale_area_vasta_txt) fl_provincia_principale_area_vasta_cv FROM src s)
 SELECT c.*,CASE WHEN cd_provincia_txt IS NULL THEN 'cd_provincia obbligatorio' WHEN duplicate_count>1 THEN 'Chiave duplicata: (cd_provincia)' WHEN length(cd_provincia_txt)>2 THEN 'cd_provincia eccede 2 caratteri' WHEN ds_nome_txt IS NULL THEN 'ds_nome obbligatorio' WHEN length(ds_nome_txt)>100 THEN 'ds_nome eccede 100 caratteri' WHEN id_sorgente_provincia_txt IS NOT NULL AND id_sorgente_provincia_cv IS NULL THEN 'id_sorgente_provincia non convertibile in bigint' WHEN id_sorgente_area_vasta_txt IS NOT NULL AND id_sorgente_area_vasta_cv IS NULL THEN 'id_sorgente_area_vasta non convertibile in bigint' WHEN fl_provincia_principale_regionale_txt IS NULL THEN 'fl_provincia_principale_regionale obbligatorio' WHEN fl_provincia_principale_regionale_cv IS NULL THEN 'fl_provincia_principale_regionale non convertibile in flag' WHEN fl_provincia_principale_area_vasta_txt IS NULL THEN 'fl_provincia_principale_area_vasta obbligatorio' WHEN fl_provincia_principale_area_vasta_cv IS NULL THEN 'fl_provincia_principale_area_vasta non convertibile in flag' ELSE NULL END::text tx_motivo_scarto FROM cv c;
 SELECT count(*) INTO v_selected FROM hcbi_ras.tmp_anag_provincia_classificata;
 INSERT INTO hcbi_ras.stg_anag_provincia(id_sorgente_provincia,cd_provincia,ds_nome,id_sorgente_area_vasta,fl_provincia_principale_regionale,fl_provincia_principale_area_vasta) SELECT id_sorgente_provincia_cv,cd_provincia_txt,ds_nome_txt,id_sorgente_area_vasta_cv,fl_provincia_principale_regionale_cv,fl_provincia_principale_area_vasta_cv FROM hcbi_ras.tmp_anag_provincia_classificata WHERE tx_motivo_scarto IS NULL; GET DIAGNOSTICS v_inserted=ROW_COUNT;
 INSERT INTO hcbi_ras.stg_anag_provincia_rej(id_sorgente_provincia,cd_provincia,ds_nome,id_sorgente_area_vasta,fl_provincia_principale_regionale,fl_provincia_principale_area_vasta,tx_motivo_scarto) SELECT id_sorgente_provincia_raw,cd_provincia_raw,ds_nome_raw,id_sorgente_area_vasta_raw,fl_provincia_principale_regionale_raw,fl_provincia_principale_area_vasta_raw,tx_motivo_scarto FROM hcbi_ras.tmp_anag_provincia_classificata WHERE tx_motivo_scarto IS NOT NULL; GET DIAGNOSTICS v_rec_errors=ROW_COUNT;
 IF v_selected<>v_inserted+v_rec_errors THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE=format('Riconciliazione non valida: selected=%s, inserted=%s, rejected=%s',v_selected,v_inserted,v_rec_errors); END IF;
 CALL hcbi_utility.pkg_log_prc_update_log(v_id_log,v_selected,v_inserted,v_updated,v_deleted,v_rec_errors,'SUCCESS',clock_timestamp()::timestamp,p_ds_step_name); DROP TABLE hcbi_ras.tmp_anag_provincia_classificata; p_result:=1;
EXCEPTION WHEN OTHERS THEN
 GET STACKED DIAGNOSTICS v_sqlstate=RETURNED_SQLSTATE,v_sqlerrm=MESSAGE_TEXT,v_sql_detail=PG_EXCEPTION_DETAIL,v_sql_hint=PG_EXCEPTION_HINT,v_sql_context=PG_EXCEPTION_CONTEXT;
 p_result:=-1; BEGIN DROP TABLE IF EXISTS hcbi_ras.tmp_anag_provincia_classificata; EXCEPTION WHEN OTHERS THEN RAISE WARNING 'Errore cleanup: SQLSTATE=%, errore=%',SQLSTATE,SQLERRM; END;
 v_log_error:=left(concat_ws(E'\n','SQLSTATE='||coalesce(v_sqlstate,''),'MESSAGE='||left(coalesce(v_sqlerrm,''),1500),CASE WHEN nullif(v_sql_detail,'') IS NOT NULL THEN 'DETAIL='||left(v_sql_detail,1000) END,CASE WHEN nullif(v_sql_hint,'') IS NOT NULL THEN 'HINT='||left(v_sql_hint,500) END,CASE WHEN nullif(v_sql_context,'') IS NOT NULL THEN 'CONTEXT='||left(v_sql_context,800) END),4000);
 IF v_id_log IS NOT NULL THEN BEGIN CALL hcbi_utility.pkg_log_prc_error_update_log(v_id_log,'FAILED',v_log_error,clock_timestamp()::timestamp,p_ds_step_name); EXCEPTION WHEN OTHERS THEN RAISE WARNING 'Errore logging: SQLSTATE=%, errore=%',SQLSTATE,SQLERRM; END; END IF;
 RAISE WARNING 'Errore in pkg_stg_anag_provincia_prc_main. SQLSTATE=%, errore=%',v_sqlstate,v_sqlerrm;
END;
$procedure$
